import {lines} from './stations.js';
import {accepts,normalize,playableStations,formatTime,accuracy} from './game.js';
import {getPlace,places} from './places.js';
import {renderMap,postcard} from './map.js';
places.gaiemmae=places.gaienmae;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allStations=new Map(lines.flatMap(l=>l.stations.map(s=>[s.id,s])));
function readSave(){try{const d=JSON.parse(localStorage.getItem('tokyo-eki-v1'));return {visited:Array.isArray(d?.visited)?d.visited.filter(id=>typeof id==='string'&&allStations.has(id)):[],records:Array.isArray(d?.records)?d.records.filter(r=>typeof r.line==='string'&&Number.isFinite(r.seconds)&&Number.isFinite(r.accuracy)).slice(0,30):[]};}catch{return {visited:[],records:[]};}}
let saved=readSave(),visited=new Set(saved.visited);
let state={line:'G',reverse:true,branch:false,mode:'travel',lang:'ko',index:0,correct:0,attempts:0,started:0,elapsed:0,status:'ready',focus:0,layer:'all',zoom:1,hints:0,sound:false};
let composing=false,audio;
const line=()=>lines.find(l=>l.id===state.line);
const route=()=>{const s=playableStations(line(),state.branch);return state.reverse?s.reverse():s;};
const target=()=>route()[state.index];
function save(){try{localStorage.setItem('tokyo-eki-v1',JSON.stringify({visited:[...visited],records:saved.records}));}catch{feedback('브라우저 저장 공간을 사용할 수 없어 이번 기록은 임시로 보관돼요.','error');}$('#collection-count').textContent=visited.size;}
function feedback(message,type=''){$('#feedback').textContent=message;$('#feedback').className=`feedback ${type}`;}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function chirp(){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.setValueAtTime(660,audio.currentTime);o.frequency.setValueAtTime(880,audio.currentTime+.09);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.22);o.start();o.stop(audio.currentTime+.23);}catch{}}
function renderLineGrid(){$('#line-grid').innerHTML=lines.map(l=>`<button class="line-option ${l.id===state.line?'active':''}" style="--line-color:${l.color}" data-line="${l.id}" aria-pressed="${l.id===state.line}"><span class="mini-badge">${l.id}</span>${esc(l.ko.replace('마루노우치','마루노우치').replace('선',''))}</button>`).join('');$$('[data-line]').forEach(b=>b.onclick=()=>{state.line=b.dataset.line;state.branch=false;state.reverse=state.line==='G';reset();});}
function renderStations(){const stations=route();$('#station-list').innerHTML=stations.map((s,i)=>`<button class="station-item ${i===state.index?'current':''} ${i<state.index?'visited':''}" data-index="${i}" aria-label="${state.mode==='memory'&&i>=state.index?'숨겨진 역':esc(s.ko)} 정보"><span class="stop"></span><span><span class="name">${state.mode==='memory'&&i>=state.index?'숨겨진 역':esc(s[state.lang])}</span><span class="roman">${esc(s.code)}</span></span><span class="code">${i<state.index?'✓':String(i+1).padStart(2,'0')}</span></button>`).join('');$$('[data-index]').forEach(b=>b.onclick=()=>{state.focus=Number(b.dataset.index);renderDiscovery();map();});}
function map(){renderMap($('#map'),{stations:route(),index:state.index,focus:state.focus,visited,layer:state.layer,zoom:state.zoom,memory:state.mode==='memory',escape:esc,onStation:i=>{state.focus=i;renderDiscovery();},onPoi:i=>{state.focus=i;renderDiscovery();}});}
function renderDiscovery(){const stations=route(),s=stations[state.focus]||stations[0];if(state.mode==='memory'&&state.focus>=state.index){$('#discovery').innerHTML=`<div class="discovery-title"><div class="discovery-eyebrow">A LITTLE SURPRISE</div><h3>어떤 동네일까요?</h3><p>역을 맞히면 이야기가 열려요</p></div><div class="postcard">${postcard('station')}</div><div class="discovery-body"><span class="place-tag">암기 여행 중</span><h4 class="place-heading">기억 속 노선을 따라가요</h4><p class="place-description">입력한 역은 여행 수첩에 기록돼요. 막히면 전구 버튼으로 이번 역의 이름을 확인할 수 있어요.</p></div>`;return;}
const p=getPlace(s);$('#discovery').innerHTML=`<div class="discovery-title"><div class="discovery-eyebrow"><span>NEIGHBORHOOD STORY</span><span>${esc(s.code)}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.ja)}</p></div><div class="postcard">${postcard(p.icon)}<span class="postcard-tag">${esc(p.tag)}</span></div><div class="discovery-body"><span class="place-tag">${p.generic?'동네 탐색':'가볼 만한 곳'}</span><h4 class="place-heading">${esc(p.sight)}<span class="place-japanese">${esc(p.sightJa)}</span></h4><p class="place-description">${esc(p.description)}</p><div class="food-card"><span class="food-icon">${p.emoji}</span><div><small>이 동네의 한 입</small><strong>${esc(p.food)}</strong><p>${esc(p.foodDescription)}</p></div></div><a class="place-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">공식 여행 안내에서 더 보기 ↗</a></div>`;}
function renderTarget(){const s=target();const hidden=state.mode==='memory';$('#target-name').textContent=s?(hidden?'다음 역은 어디일까요?':s[state.lang]):'종점에 도착했어요';$('#target-code').textContent=s?.code||'✓';$('#target-translations').textContent=s?(hidden?'노선 순서를 떠올려 보세요':state.lang==='ko'?`${s.en} · ${s.ja}`:`${s.ko} · ${state.lang==='en'?s.ja:s.en}`):'또 다른 노선으로 여행을 이어가세요';$('#target-label').textContent=state.status==='done'?'JOURNEY COMPLETE · 여행 완료':'NEXT STATION · 다음 역';$('#accuracy').innerHTML=`${accuracy(state.correct,state.attempts)}<small>%</small>`;$('#progress-count').innerHTML=`${state.index}<small>/ ${route().length}</small>`;$('#progress-bar').style.width=`${state.index/route().length*100}%`;$('#start-button').innerHTML=state.status==='ready'?'여행 시작 <span>→</span>':state.status==='running'?'입력 <span>↵</span>':'다시 여행 <span>→</span>';$('#time-label').textContent=state.mode==='time'?'남은 시간':'여행 시간';updateClock();}
function render(){const l=line(),stations=route();document.documentElement.style.setProperty('--accent',l.color);renderLineGrid();$('#line-badge').textContent=l.id;$('#line-name').textContent=l.ko;$('#line-english').textContent=l.en;$('#station-total').textContent=`${stations.length}개 역`;$('#direction-description').textContent=`${stations[0].ko} → ${stations.at(-1).ko}`;$('#map-line-label').textContent=l.ko;
let branch=$('#branch-toggle');if(!branch){branch=document.createElement('button');branch.id='branch-toggle';branch.className='text-button';branch.style.cssText='margin:0 18px 12px;padding:7px 0;text-decoration:underline';$('.route-summary').before(branch);branch.onclick=()=>{state.branch=!state.branch;state.reverse=false;reset();};}branch.hidden=l.id!=='M';branch.textContent=state.branch?'본선으로 바꾸기 ↗':'호난초 지선으로 바꾸기 ↗';renderStations();renderTarget();renderDiscovery();map();}
function reset(){Object.assign(state,{index:0,correct:0,attempts:0,started:0,elapsed:0,status:'ready',focus:0,zoom:1,hints:0});$('#station-input').value='';feedback(state.mode==='time'?'120초 안에 최대한 많은 역을 입력해 보세요.':state.mode==='memory'?'역 이름을 가리고 순서를 기억해 입력해요. 전구를 누르면 힌트를 볼 수 있어요.':'여행 시작을 누르면 첫 역부터 출발해요.');render();}
function start(){state.status='running';state.started=performance.now();$('#station-input').value='';$('#station-input').focus();feedback('출발했어요! 역 이름을 입력하고 Enter를 눌러 주세요.');renderTarget();}
function updateClock(){if(state.status==='running')state.elapsed=Math.floor((performance.now()-state.started)/1000);$('#time').textContent=formatTime(state.mode==='time'?Math.max(0,120-state.elapsed):state.elapsed);}
function finish(timeout=false){if(state.status!=='running')return;updateClock();state.status='done';const complete=state.index===route().length;if(complete)saved.records.unshift({line:line().ko,branch:state.branch,mode:state.mode,seconds:state.elapsed,accuracy:accuracy(state.correct,state.attempts),hints:state.hints,date:new Date().toISOString()});saved.records=saved.records.slice(0,30);save();renderTarget();feedback(complete?'완주했어요! 발견한 동네는 여행 수첩에 담았어요.':'시간이 끝났어요. 도착한 동네는 여행 수첩에 담았어요.','success');modal(`<p class="eyebrow">${complete?'A JOURNEY TO REMEMBER':'TIME IS UP'}</p><h2>${complete?'종점에 도착했어요!':'이번 여행은 여기까지'}</h2><p>${esc(line().ko)} ${state.branch?'지선 ':''}· ${esc({travel:'여행 모드',memory:'암기 모드',time:'타임어택'}[state.mode])}</p><div class="result-number">${state.index}<small style="font-size:18px"> / ${route().length} 역</small></div><p>여행 시간 ${formatTime(state.elapsed)} · 정확도 ${accuracy(state.correct,state.attempts)}%<br>사용한 힌트 ${state.hints}회 · 수첩에 모은 동네 ${visited.size}곳</p><button class="primary" id="result-close">여행 이어가기 →</button>`);$('#result-close').onclick=()=>$('#modal').close();}
$('#typing-form').addEventListener('submit',e=>{e.preventDefault();if(composing)return;if(state.status==='done'){reset();start();return;}if(state.status==='ready'){start();return;}updateClock();if(state.mode==='time'&&state.elapsed>=120){finish(true);return;}const value=$('#station-input').value;if(!normalize(value)){feedback('역 이름을 입력해 주세요.');return;}state.attempts++;if(!accepts(target(),value)){feedback('조금 달라요. 역 이름을 확인하고 다시 입력해 보세요.','error');$('#typing-form').classList.remove('shake');void $('#typing-form').offsetWidth;$('#typing-form').classList.add('shake');renderTarget();return;}const s=target();state.correct++;visited.add(s.id);state.focus=state.index;state.index++;$('#station-input').value='';save();chirp();renderStations();renderTarget();renderDiscovery();map();feedback(`${s.ko} 도착! 동네 이야기 하나를 수첩에 담았어요.`,'success');if(state.index===route().length)finish();});
$('#station-input').addEventListener('compositionstart',()=>composing=true);$('#station-input').addEventListener('compositionend',()=>composing=false);$('#station-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.isComposing||e.keyCode===229))e.preventDefault();});
$('#reverse').onclick=()=>{state.reverse=!state.reverse;reset();};$('#restart').onclick=reset;
$$('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));reset();});
$$('[data-lang]').forEach(b=>b.onclick=()=>{state.lang=b.dataset.lang;$$('[data-lang]').forEach(x=>x.classList.toggle('active',x===b));renderTarget();renderStations();});
$$('[data-layer]').forEach(b=>b.onclick=()=>{state.layer=b.dataset.layer;$$('[data-layer]').forEach(x=>x.classList.toggle('selected',x===b));map();});
$('#hint').onclick=()=>{if(!target())return;state.hints++;$('#target-name').textContent=target()[state.lang];$('#target-translations').textContent=`${target().ko} · ${target().en} · ${target().ja}`;feedback(`힌트: ${target().ko} · ${target().en} · ${target().ja}`);};
$('#sound').onclick=()=>{state.sound=!state.sound;$('#sound').textContent=`♪ 소리 ${state.sound?'켜짐':'꺼짐'}`;$('#sound').setAttribute('aria-pressed',state.sound);chirp();};
$('#zoom-in').onclick=()=>{state.zoom=Math.min(2.5,state.zoom+.25);map();};$('#zoom-out').onclick=()=>{state.zoom=Math.max(1,state.zoom-.25);map();};$('#zoom-reset').onclick=()=>{state.zoom=1;map();};
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
$('#help').onclick=()=>modal(`<p class="eyebrow">WELCOME ABOARD</p><h2>도쿄로 떠나는 작은 타이핑 여행</h2><ol><li>왼쪽에서 노선을 고르고 진행 방향을 선택하세요.</li><li><strong>여행 시작</strong>을 누른 뒤, 표시된 역 이름을 순서대로 입력하고 Enter를 누르세요.</li><li>한국어, 영어, 일본어 중 어느 언어든 입력할 수 있어요. 영문 대소문자와 띄어쓰기, 하이픈 차이는 무시해요.</li><li>역을 클릭하면 주변 명소와 먹거리가 오른쪽에 나타나요. 지도는 실제 거리를 단순화한 학습용 개략도예요.</li></ol><p><strong>여행 모드</strong> 이름을 보며 천천히 익혀요.<br><strong>암기 모드</strong> 이름을 가리고 순서에 도전해요.<br><strong>타임어택</strong> 120초 동안 최대한 멀리 가요.</p><p>역 이름과 한자를 입력한 뒤 일본어 IME 조합을 확정하고 Enter를 한 번 더 누르세요. 기록은 이 브라우저에 저장되며 다른 기기와 동기화되지 않아요.</p>`);
$('#sources').onclick=()=>modal(`<h2>자료와 지도 안내</h2><p>역 이름·번호·노선 순서는 <a href="https://www.tokyometro.jp/kr/subwaymap/index.html" target="_blank" rel="noopener noreferrer">도쿄메트로 공식 자료</a>를 기준으로 작성했어요. 확인일: 2026년 10월 30일.</p><p>이 게임은 도쿄메트로 9개 노선을 다룹니다. 도에이 지하철, JR, 사철은 포함하지 않아요. 마루노우치선 지선은 별도로 선택할 수 있어요.</p><p>긴자선 전 역과 주요 관광역에는 동네 이야기가 있어요. 다른 역의 개별 명소·먹거리 정보는 준비 중이며, 해당 역에는 공식 관광 안내 링크가 표시돼요.</p><p>관광 내용은 <a href="https://www.gotokyo.org/kr/" target="_blank" rel="noopener noreferrer">GO TOKYO</a>와 <a href="https://www.japan.travel/en/" target="_blank" rel="noopener noreferrer">JNTO</a> 관광 안내를 참고했어요. 각 역 카드에서 관련 안내를 열 수 있어요. 지도의 명소 위치는 이해를 돕기 위해 단순화했으며 이동 경로 안내용이 아니에요.</p><p>역을 순서대로 입력하는 게임 방식은 <a href="https://metrotyping.kr/" target="_blank" rel="noopener noreferrer">Metro Typing</a>을 참고했어요. 화면과 지도 삽화는 새로 제작한 비공식 학습 프로젝트예요.</p>`);
function journal(){const stations=[...visited].map(id=>allStations.get(id)).filter(Boolean);$('#journal-stats').textContent=`발견한 동네 ${stations.length}곳 · 완주한 여행 ${saved.records.length}회`;$('#journal-places').innerHTML=stations.length?stations.map(s=>{const p=getPlace(s);return `<article class="journal-card"><h3>${p.emoji} ${esc(s.ko)}</h3><span>${esc(s.en)} · ${esc(s.ja)}</span><p>${esc(p.generic?'이름을 익힌 동네':p.sight)}</p></article>`;}).join(''):'<p class="empty-state">아직 빈 수첩이에요. 첫 번째 역에 도착하면 나만의 도쿄 여행이 기록돼요.</p>';$('#journal-records').innerHTML=saved.records.length?saved.records.map(r=>`<div>${esc(r.date?.slice(0,10)||'')} · ${esc(r.line)} ${r.branch?'지선':''} · ${esc({travel:'여행',memory:'암기',time:'타임어택'}[r.mode]||'여행')} · ${formatTime(r.seconds)} · 정확도 ${r.accuracy}% · 힌트 ${Number(r.hints)||0}회</div>`).join(''):'아직 완주 기록이 없어요. 한 노선을 끝까지 달려 보세요.';}
$$('[data-view]').forEach(b=>b.onclick=()=>{const show=b.dataset.view==='play';$('#play-view').hidden=!show;$('#collection-view').hidden=show;$$('[data-view]').forEach(x=>x.classList.toggle('active',x===b));if(!show)journal();});
$('#export-journal').onclick=()=>{const blob=new Blob([JSON.stringify({title:'도쿄 한 정거장 여행 수첩',exportedAt:new Date().toISOString(),stations:[...visited].map(id=>allStations.get(id)),records:saved.records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tokyo-eki-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
setInterval(()=>{if(state.status==='running'){updateClock();if(state.mode==='time'&&state.elapsed>=120)finish(true);}},250);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.status==='running'){updateClock();if(state.mode==='time'&&state.elapsed>=120)finish(true);}});
$('#collection-count').textContent=visited.size;render();
